1	#version 460
2	#include "common.glsl"
3	layout(local_size_x=128) in;
4	void main(){
5	 uint lane=gl_LocalInvocationID.x%32;
6	 uint row=gl_WorkGroupID.x*4+gl_LocalInvocationID.x/32;
7	 if(row>=p.b)return;
8	 float sum=0;
9	 if(p.c==143){
10	  uint nb=p.a/128;
11	  for(uint b=0;b<nb;b++){
12	   uint base=(row*nb+b)*7;
13	   uint q=(I(p.w).d[base+lane/4]>>(8*(lane%4)))&255;
14	   float scale=unpackHalf2x16(I(p.w).d[base+6]>>16).x;
15	   uint start=lane<16?lane:(lane<24?80+lane-16:120+lane-24);
16	   uint step=lane<16?16:(lane<24?8:2);
17	   float s=0;
18	   if(lane<26){
19	    s+=float(int((q*3)>>8)-1)*F(p.x).d[b*128+start];q=(q*3)&255;
20	    s+=float(int((q*3)>>8)-1)*F(p.x).d[b*128+start+step];q=(q*3)&255;
21	    s+=float(int((q*3)>>8)-1)*F(p.x).d[b*128+start+step*2];q=(q*3)&255;
22	    s+=float(int((q*3)>>8)-1)*F(p.x).d[b*128+start+step*3];q=(q*3)&255;
23	    if(lane<24)s+=float(int((q*3)>>8)-1)*F(p.x).d[b*128+start+step*4];
24	   }
25	   sum+=s*scale;
26	  }
27	 }else{
28	  for(uint k=lane;k<p.a;k+=32)sum+=F(p.w).d[row*p.a+k]*F(p.x).d[k];
29	 }
30	 sum=subgroupAdd(sum);if(lane==0)F(p.y).d[row]=sum;
31	}
