#version 460
#include "common.glsl"
#extension GL_KHR_cooperative_matrix : require
#extension GL_KHR_memory_scope_semantics : require

// X[token,input], W[output,input], Y[token,output].
// p.a=input width, p.b=output width, p.c=GGML type, p.d=token count.
// Workgroup tile: 16 tokens x64 output rows; four subgroup32 16x16 MMAs.
// Dispatch (ceil(outputwidth/64), ceil(tokens/16), 1).
layout(local_size_x=128) in;
shared float16_t input_tile[16*128];
shared float16_t weight_tile[64*128];
shared float output_tile[16*64];

float unpack_weight(uint row,uint col) {
    if (row>=p.b || col>=p.a) return 0.0;
    if (p.c!=143) return F(p.w).d[row*p.a+col];
    uint block=row*(p.a/128)+col/128;
    uint pos=col%128;
    uint packed_index=pos<80?pos%16:(pos<120?16+(pos-80)%8:24+(pos-120)%2);
    uint digit=pos<80?pos/16:(pos<120?(pos-80)/8:(pos-120)/2);
    const uint powers[5]=uint[5](1,3,9,27,81);
    uint packed=(I(p.w).d[block*7+packed_index/4]>>(8*(packed_index%4)))&255;
    int trit=int((((packed*powers[digit])&255)*3)>>8)-1;
    float scale=unpackHalf2x16(I(p.w).d[block*7+6]>>16).x;
    return float(trit)*scale;
}

void main() {
    uint local=gl_LocalInvocationID.x;
    uint subgroup=gl_SubgroupID;
    uint row_base=gl_WorkGroupID.x*64;
    uint token_base=gl_WorkGroupID.y*16;
    coopmat<float,gl_ScopeSubgroup,16,16,gl_MatrixUseAccumulator> accum=coopmat<float,gl_ScopeSubgroup,16,16,gl_MatrixUseAccumulator>(0.0);
    for(uint k_base=0;k_base<p.a;k_base+=128) {
        for(uint index=local;index<16*128;index+=128) {
            uint token=token_base+index/128;
            uint col=k_base+index%128;
            input_tile[index]=float16_t(token<p.d && col<p.a?F(p.x).d[token*p.a+col]:0.0);
        }
        for(uint index=local;index<64*128;index+=128) {
            weight_tile[index]=float16_t(unpack_weight(row_base+index/128,k_base+index%128));
        }
        barrier();
        for(uint kk=0;kk<128;kk+=16) {
            coopmat<float16_t,gl_ScopeSubgroup,16,16,gl_MatrixUseA> input_matrix;
            coopmat<float16_t,gl_ScopeSubgroup,16,16,gl_MatrixUseB> weight_matrix;
            coopMatLoad(input_matrix,input_tile,kk,128,gl_CooperativeMatrixLayoutRowMajor);
            // W stores each output column contiguously along K.
            coopMatLoad(weight_matrix,weight_tile,subgroup*16*128+kk,128,gl_CooperativeMatrixLayoutColumnMajor);
            accum=coopMatMulAdd(input_matrix,weight_matrix,accum);
        }
        barrier();
    }
    coopMatStore(accum,output_tile,subgroup*16,64,gl_CooperativeMatrixLayoutRowMajor);
    barrier();
    for(uint index=local;index<16*64;index+=128) {
        uint token=token_base+index/64;
        uint row=row_base+index%64;
        if(token<p.d && row<p.b) F(p.y).d[token*p.b+row]=output_tile[index];
    }
}

const std = @import("std");
const vk = @import("vk");
const model = @import("model");
const c = vk.c;
const Params = extern struct { w: u64 = 0, x: u64 = 0, y: u64 = 0, z: u64 = 0, s: u64 = 0, t: u64 = 0, u: u64 = 0, v: u64 = 0, a: u32 = 0, b: u32 = 0, c: u32 = 0, d: u32 = 0, e: u32 = 0, f: u32 = 0, g: u32 = 0, h: u32 = 0 };
pub fn main() !void {
    var gpu = try vk.Runtime.init();
    defer gpu.deinit();
    const get_props: c.PFN_vkGetPhysicalDeviceCooperativeMatrixPropertiesKHR = @ptrCast(c.vkGetInstanceProcAddr(gpu.instance, "vkGetPhysicalDeviceCooperativeMatrixPropertiesKHR"));
    var count: u32 = 0;
    try vk.check(get_props.?(gpu.physical, &count, null));
    var props: [128]c.VkCooperativeMatrixPropertiesKHR = undefined;
    for (&props) |*p| { p.* = std.mem.zeroes(c.VkCooperativeMatrixPropertiesKHR); p.sType = c.VK_STRUCTURE_TYPE_COOPERATIVE_MATRIX_PROPERTIES_KHR; }
    try vk.check(get_props.?(gpu.physical, &count, &props));
    for (props[0..count]) |p| std.debug.print("COOP {d}x{d}x{d} A={d} B={d} C={d} R={d} scope={d}\n", .{p.MSize,p.NSize,p.KSize,p.AType,p.BType,p.CType,p.ResultType,p.scope});
    const mm = try gpu.pipeline(@alignCast(@embedFile("model_matmul.spv")));
    defer c.vkDestroyPipeline(gpu.device, mm, null);
    const mv = try gpu.pipeline(@alignCast(@embedFile("model_matvec.spv")));
    defer c.vkDestroyPipeline(gpu.device, mv, null);
    var gg = try model.Model.open(std.heap.page_allocator, "/workspace/data/Ternary-Bonsai-2-4B-PTQ1_0.gguf");
    defer gg.deinit();
    var weights = try gpu.buffer(gg.weights.len);
    defer gpu.freeBuffer(&weights);
    @memcpy(weights.ptr[0..gg.weights.len], gg.weights);
    var x = try gpu.buffer(17*9216*4);
    defer gpu.freeBuffer(&x);
    var y = try gpu.buffer(17*9216*4);
    defer gpu.freeBuffer(&y);
    var ref = try gpu.buffer(17*9216*4);
    defer gpu.freeBuffer(&ref);
    const xp: [*]f32 = @ptrCast(@alignCast(x.ptr));
    for (0..17*9216) |i| xp[i] = switch (i%7) { 0=>1.0, 1=>-0.25, 2=>0.125, 3=>-2.0, 4=>0.375, 5=>0.0, else=>0.03125 };
    for ([_][]const u8{"blk.0.ffn_gate.weight","blk.0.ffn_down.weight","blk.0.ssm_out.weight","blk.0.ssm_alpha.weight"}) |name| {
        const tensor = gg.findTensor(name).?;
        const a:u32 = @intCast(tensor.dims[0]); const b:u32 = @intCast(tensor.dims[1]);
        try gpu.begin();
        for (0..17) |token| gpu.dispatch(mv, Params{.w=weights.addr+tensor.offset,.x=x.addr+token*a*4,.y=ref.addr+token*b*4,.a=a,.b=b,.c=tensor.typ}, (b+3)/4, 1, 1);
        gpu.dispatch(mm, Params{.w=weights.addr+tensor.offset,.x=x.addr,.y=y.addr,.a=a,.b=b,.c=tensor.typ,.d=17}, (b+63)/64, 2, 1);
        try gpu.finish();
        const got:[*]const f32 = @ptrCast(@alignCast(y.ptr)); const want:[*]const f32 = @ptrCast(@alignCast(ref.ptr));
        var max_err:f32=0; var squared:f64=0; var scale:f64=0;
        for (0..17*b) |i| { const diff=got[i]-want[i]; max_err=@max(max_err,@abs(diff)); squared+=@as(f64,diff)*diff; scale+=@as(f64,want[i])*want[i]; }
        std.debug.print("CHECK {s} max_error={d:.8} relative_rms={d:.8} first={d:.8}/{d:.8} last={d:.8}/{d:.8}\n",.{name,max_err,@sqrt(squared/scale),got[0],want[0],got[17*b-1],want[17*b-1]});
        if (!(max_err < 0.05)) return error.Mismatch;
    }
}

