// RDNA4 subgroup32 fragment layout recovered with the standalone GPU probe
// tools/model_coopmap.comp: a[i]=(lane%16,lane/16*8+i),
// b[i]=c[i]=(lane/16*8+i,lane%16), for i=0..7.
// Direct register fragments avoid LDS expansion, bank conflicts and barriers.
// Same contract as matmul.comp:16tokens x64out,local128,dispatch(out/64,tokens/16).
layout(local_size_x=128) in;

float weight(uint row,uint col) {
    if(row>=p.b || col>=p.a)return 0.0;
    if(p.c!=143)return F(p.w).d[row*p.a+col];
    uint block=row*(p.a/128)+col/128;
    uint pos=col%128;
    uint packed_index=pos<80?pos%16:(pos<120?16+(pos-80)%8:24+(pos-120)%2);
    uint digit=pos<80?pos/16:(pos<120?(pos-80)/8:(pos-120)/2);
    const uint powers[5]=uint[5](1,3,9,27,81);
    uint packed=(I(p.w).d[block*7+packed_index/4]>>(8*(packed_index%4)))&255;
    int trit=int((((packed*powers[digit])&255)*3)>>8)-1;
    float scale=unpackHalf2x16(I(p.w).d[block*7+6]>>16).x;
    return float(trit)*scale;
}

void main(){
    uint lane=gl_SubgroupInvocationID;
    uint row=gl_WorkGroupID.x*64+gl_SubgroupID*16+lane%16;
    uint token_base=gl_WorkGroupID.y*16;
    uint token=token_base+lane%16;
    uint half_offset=lane/16*8;
    coopmat<float,gl_ScopeSubgroup,16,16,gl_MatrixUseAccumulator> accum=coopmat<float,gl_ScopeSubgroup,16,16,gl_MatrixUseAccumulator>(0.0);
    for(uint k=0;k<p.a;k+=16){
        coopmat<float16_t,gl_ScopeSubgroup,16,16,gl_MatrixUseA> a;
        coopmat<float16_t,gl_ScopeSubgroup,16,16,gl_MatrixUseB> b;
        for(uint i=0;i<8;i++){
            uint col=k+half_offset+i;
            a[i]=float16_t(token<p.d && col<p.a?F(p.x).d[token*p.a+col]:0.0);
            b[i]=float16_t(weight(row,col));
        }
        accum=coopMatMulAdd(a,b,accum);
    }
    for(uint i=0;i<8;i++){
        uint out_token=token_base+half_offset+i;
        if(out_token<p.d && row<p.b)F(p.y).d[out_token*p.b+row]=accum[i];
    }
}

