65	export fn bonsai_tensor_info(m: ?*const Model, index: i32, name: ?*?[*:0]const u8, typ: ?*i32, rank: ?*i32, ne: ?[*]i64) i32 {
66	    clear();
67	    if (m == null or index < 0 or index >= m.?.gguf.tensors.len) return fail("invalid tensor index", -1);
68	    const t = &m.?.gguf.tensors[@intCast(index)];
69	    if (name) |p| p.* = t.name.ptr;
70	    if (typ) |p| p.* = @intCast(t.typ);
71	    if (rank) |p| p.* = @intCast(t.n_dims);
72	    if (ne) |p| for (0..4) |i| {
73	        p[i] = @intCast(t.dims[i]);
74	    };
75	    return 0;
76	}
77	export fn bonsai_tensor_dequant(m: ?*const Model, name: ?[*:0]const u8, out: ?[*]f32, capacity: i64) i64 {
78	    clear();
79	    if (m == null or name == null or capacity < 0) return fail("invalid dequant arguments", -1);
80	    const t = m.?.gguf.findTensor(std.mem.span(name.?)) orelse return fail("tensor not found", -1);
81	    const n = t.elementCount();
82	    if (out == null or capacity < n) return fail("dequant output capacity", -2);
83	    t.dequant(out.?[0..n]) catch |e| return err(e);
84	    return @intCast(n);
