96	                try self.expectLayer(l, "attn_gate.weight", 2560, 4096, 143);
97	                try self.expectLayer(l, "ssm_out.weight", 4096, 2560, 143);
98	                try self.expectLayer(l, "ssm_alpha.weight", 2560, 32, 0);
99	                try self.expectLayer(l, "ssm_beta.weight", 2560, 32, 0);
100	                try self.expectLayer(l, "ssm_a", 32, 0, 0);
101	                try self.expectLayer(l, "ssm_dt.bias", 32, 0, 0);
102	                try self.expectLayer(l, "ssm_norm.weight", 128, 0, 0);
103	                try self.expectLayer(l, "ssm_conv1d.weight", 4, 8192, 0);
