106	                try self.expectLayer(l, "attn_k.weight", 2560, 1024, 143);
107	                try self.expectLayer(l, "attn_v.weight", 2560, 1024, 143);
108	                try self.expectLayer(l, "attn_output.weight", 4096, 2560, 143);
109	                try self.expectLayer(l, "attn_q_norm.weight", 256, 0, 0);
110	                try self.expectLayer(l, "attn_k_norm.weight", 256, 0, 0);
