253	    fn layerName(buf: []u8, layer: u32, suffix: []const u8) ![]const u8 {
254	        return std.fmt.bufPrint(buf, "blk.{d}.{s}", .{ layer, suffix });
255	    }
256	    fn layerMat(self: *Context, layer: u32, suffix: []const u8, x: u64, y: u64) !void {
