273	        var full: u64 = 0;
274	        for (0..32) |li| {
275	            const l: u32 = @intCast(li);
276	            try self.layerNorm(l, "attn_norm.weight", self.x, self.norm, 2560, 1, 0);
277	            self.had(self.norm, self.trans, 2560, false);
278	            if ((l + 1) % 4 != 0) {
279	                try self.layerMat(l, "attn_qkv.weight", self.trans, self.qkv);
280	                try self.layerMat(l, "attn_gate.weight", self.trans, self.gate);
281	                try self.layerMat(l, "ssm_alpha.weight", self.norm, self.alpha);
282	                try self.layerMat(l, "ssm_beta.weight", self.norm, self.beta);
