284	                m.dispatch(.gdn, .{ .w = try self.layerAddr(l, "ssm_dt.bias"), .x = self.conv, .y = self.att, .z = try self.layerAddr(l, "ssm_a"), .s = self.gdn_state + linear * 32 * 128 * 128 * 4, .t = self.alpha, .u = self.beta }, 64, 1);
