287	                try self.layerMat(l, "ssm_out.weight", self.trans, self.down);
288	                linear += 1;
289	            } else {
290	                try self.layerMat(l, "attn_q.weight", self.trans, self.qkv);
291	                try self.layerMat(l, "attn_k.weight", self.trans, self.k);
292	                try self.layerMat(l, "attn_v.weight", self.trans, self.v);
293	                const cache = self.kv + full * 2 * @as(u64, self.kv_stride) * 1024 * 2;
294	                m.dispatch(.attprep, .{ .w = try self.layerAddr(l, "attn_q_norm.weight"), .x = self.qkv, .y = self.q, .z = self.qgate, .a = self.pos, .b = 0 }, 16, 1);
