403	    pub fn eval(self: *Context, tokens: []const i32, logits: ?[*]f32) !void {
404	        if (tokens.len == 0 or tokens.len > self.n_ctx - self.pos) return error.ContextCapacity;
405	        for (tokens) |id| if (id < 0 or id >= self.model.n_vocab) return error.InvalidToken;
406	        // A layer-major batch reuses packed weights and matrix cores for prefill.
407	        var i: usize = 0;
408	        while (i < tokens.len) {
409	            const end = @min(i + batch_size, tokens.len);
410	            try self.model.gpu.begin();
411	            if (end - i >= 8) {
412	                try self.forwardBatch(tokens[i..end], end == tokens.len);
413	            } else {
414	                for (tokens[i..end], i..) |id, j| try self.forward(id, j + 1 == tokens.len);
415	            }
416	            try self.model.gpu.finish();
417	            i = end;
418	        }
419	        if (logits) |out| {
420	            const off: usize = @intCast(self.logits - self.work.addr);
421	            const src: [*]const f32 = @ptrCast(@alignCast(self.work.ptr + off));
422	            @memcpy(out[0..self.model.n_vocab], src[0..self.model.n_vocab]);
423	        }
424	    }
425	    pub fn best(self: *Context) !i32 {
426	        try self.model.gpu.begin();
427	        const groups = (self.model.n_vocab + 1023) / 1024;
428	        self.model.dispatch(.argmax, .{ .x = self.logits, .y = self.argmax, .a = self.model.n_vocab }, groups, 1);
429	        self.model.dispatch(.argmax, .{ .x = self.argmax, .y = self.argmax, .a = groups, .b = 1 }, 1, 1);
430	        try self.model.gpu.finish();
431	        const ptr: *const i32 = @ptrCast(@alignCast(self.work.ptr + @as(usize, @intCast(self.argmax - self.work.addr))));
432	        return ptr.*;
433	    }
434	};
