100	    ctx.?.reset() catch |e| return err(e);
101	    return 0;
102	}
103	export fn bonsai_eval(ctx: ?*Context, tokens: ?[*]const i32, n_tokens: i32, logits: ?[*]f32, capacity: i32) i32 {
104	    clear();
105	    if (ctx == null or tokens == null or n_tokens < 1 or capacity < 0) return fail("invalid eval arguments", -1);
106	    if (logits != null and capacity < ctx.?.model.n_vocab) return fail("logits output capacity", -2);
107	    ctx.?.eval(tokens.?[0..@intCast(n_tokens)], logits) catch |e| return err(e);
108	    return 0;
109	}
110	export fn bonsai_generate_greedy(ctx: ?*Context, prompt: ?[*]const i32, n_prompt: i32, n_predict: i32, flags: u32, out: ?[*]i32) i32 {
111	    clear();
112	    if (ctx == null or n_prompt < 0 or n_predict < 0 or (n_prompt > 0 and prompt == null) or (n_predict > 0 and out == null)) return fail("invalid generation arguments", -1);
113	    const p = ctx.?;
114	    if (@as(u64, @intCast(n_prompt)) + @as(u64, @intCast(n_predict)) > p.n_ctx - p.pos) return fail("generation context capacity", -2);
115	    if (n_prompt > 0) {
116	        p.eval(prompt.?[0..@intCast(n_prompt)], null) catch |e| return err(e);
117	    } else if (p.pos == 0 and n_predict > 0) return fail("generation needs prompt or evaluated context", -5);
118	    var count: i32 = 0;
119	    while (count < n_predict) {
120	        const id = p.best() catch |e| return err(e);
121	        out.?[@intCast(count)] = id;
122	        count += 1;
123	        if (id == p.model.eos and (flags & 1) == 0) break;
124	        const one = [_]i32{id};
125	        p.eval(&one, null) catch |e| return err(e);
126	    }
127	    return count;
128	}
