268	    fn forward(self: *Context, token: i32, with_logits: bool) !void {
269	        const m = self.model;
270	        m.dispatch(.embed, .{ .w = try m.addr("token_embd.weight"), .y = self.tmp, .a = 2560, .b = @intCast(token) }, 10, 1);
271	        self.had(self.tmp, self.x, 2560, true);
272	        var linear: u64 = 0;
273	        var full: u64 = 0;
274	        for (0..32) |li| {
275	            const l: u32 = @intCast(li);
276	            try self.layerNorm(l, "attn_norm.weight", self.x, self.norm, 2560, 1, 0);
277	            self.had(self.norm, self.trans, 2560, false);
278	            if ((l + 1) % 4 != 0) {
279	                try self.layerMat(l, "attn_qkv.weight", self.trans, self.qkv);
280	                try self.layerMat(l, "attn_gate.weight", self.trans, self.gate);
281	                try self.layerMat(l, "ssm_alpha.weight", self.norm, self.alpha);
282	                try self.layerMat(l, "ssm_beta.weight", self.norm, self.beta);
283	                m.dispatch(.conv, .{ .w = try self.layerAddr(l, "ssm_conv1d.weight"), .x = self.qkv, .y = self.conv, .s = self.conv_state + linear * 8192 * 3 * 4 }, 32, 1);
284	                m.dispatch(.gdn, .{ .w = try self.layerAddr(l, "ssm_dt.bias"), .x = self.conv, .y = self.att, .z = try self.layerAddr(l, "ssm_a"), .s = self.gdn_state + linear * 32 * 128 * 128 * 4, .t = self.alpha, .u = self.beta }, 64, 1);
285	                try self.layerNorm(l, "ssm_norm.weight", self.att, self.tmp, 128, 32, self.gate);
286	                self.had(self.tmp, self.trans, 4096, false);
287	                try self.layerMat(l, "ssm_out.weight", self.trans, self.down);
288	                linear += 1;
289	            } else {
290	                try self.layerMat(l, "attn_q.weight", self.trans, self.qkv);
291	                try self.layerMat(l, "attn_k.weight", self.trans, self.k);
292	                try self.layerMat(l, "attn_v.weight", self.trans, self.v);
293	                const cache = self.kv + full * 2 * @as(u64, self.kv_stride) * 1024 * 2;
294	                m.dispatch(.attprep, .{ .w = try self.layerAddr(l, "attn_q_norm.weight"), .x = self.qkv, .y = self.q, .z = self.qgate, .a = self.pos, .b = 0 }, 16, 1);
295	                m.dispatch(.attprep, .{ .w = try self.layerAddr(l, "attn_k_norm.weight"), .x = self.k, .y = cache, .z = cache + @as(u64, self.kv_stride) * 1024 * 2, .s = self.v, .a = self.pos, .b = 1 }, 4, 1);
296	                m.dispatch(.attscore, .{ .w = cache, .x = self.q, .y = self.scores, .a = self.pos + 1, .b = self.n_ctx }, (self.pos + 4) / 4, 16);
297	                m.dispatch(.softmax, .{ .x = self.scores, .a = self.pos + 1, .b = self.n_ctx }, 16, 1);
298	                const splits = @min(128, (self.pos + 64) / 64);
299	                m.dispatch(.attvalue, .{ .w = cache + @as(u64, self.kv_stride) * 1024 * 2, .x = self.scores, .y = if (splits > 1) self.tmp else self.att, .a = self.pos + 1, .b = self.n_ctx, .c = splits }, 16, splits);
300	                if (splits > 1) m.dispatch(.attreduce, .{ .x = self.tmp, .y = self.att, .a = splits }, 16, 1);
301	                self.elem(self.att, self.qgate, self.tmp, 4096, 2);
302	                self.had(self.tmp, self.trans, 4096, false);
303	                try self.layerMat(l, "attn_output.weight", self.trans, self.down);
304	                full += 1;
305	            }
306	            self.elem(self.x, self.down, self.x, 2560, 0);
307	            try self.layerNorm(l, "post_attention_norm.weight", self.x, self.norm, 2560, 1, 0);
308	            self.had(self.norm, self.trans, 2560, false);
309	            try self.layerMat(l, "ffn_gate.weight", self.trans, self.fg);
310	            try self.layerMat(l, "ffn_up.weight", self.trans, self.fu);
311	            self.elem(self.fg, self.fu, self.mid, 9216, 1);
312	            self.had(self.mid, self.trans, 9216, false);
313	            try self.layerMat(l, "ffn_down.weight", self.trans, self.down);
314	            self.elem(self.x, self.down, self.x, 2560, 0);
315	        }
316	        if (with_logits) {
317	            try self.normOp("output_norm.weight", self.x, self.norm, 2560, 1, 0);
318	            self.had(self.norm, self.trans, 2560, false);
319	            try self.mat("token_embd.weight", self.trans, self.logits);
320	        }
321	        self.pos += 1;
322	    }
