326	    fn matBatch(self: *Context, name: []const u8, x: u64, y: u64, n: u32) !void {
327	        const t = try self.model.tensor(name);
328	        const width: u32 = @intCast(t.dims[0]);
329	        const rows: u32 = @intCast(t.dims[1]);
330	        const count = width * rows;
331	        if (t.typ == 143 and n >= 128) {
332	            self.model.dispatch(.dequant_tiled, .{ .w = self.model.weights.addr + t.offset, .y = self.weights16, .a = width, .b = rows, .c = t.typ }, (rows + 15) / 16, width / 128);
333	            self.model.dispatch(.cast_tiled, .{ .x = x, .y = self.inputs16, .a = width, .d = n }, (n + 15) / 16, width / 128);
334	            self.model.dispatch(.matmul_f16_tiled, .{ .w = self.weights16, .x = self.inputs16, .y = y, .a = width, .b = rows, .d = n }, (rows + 63) / 64, (n + 63) / 64);
335	        } else {
336	            self.model.dispatch(.dequant, .{ .w = self.model.weights.addr + t.offset, .y = self.weights16, .a = count, .c = t.typ }, if (t.typ == 143) (count + 511) / 512 else (count + 127) / 128, 1);
