361	            if ((l + 1) % 4 != 0) {
362	                try self.layerMatBatch(l, "attn_qkv.weight", self.trans, self.qkv, n);
363	                try self.layerMatBatch(l, "attn_gate.weight", self.trans, self.gate, n);
364	                try self.layerMatBatch(l, "ssm_alpha.weight", self.norm, self.alpha, n);
365	                try self.layerMatBatch(l, "ssm_beta.weight", self.norm, self.beta, n);
366	                m.dispatch(.conv, .{ .w = try self.layerAddr(l, "ssm_conv1d.weight"), .x = self.qkv, .y = self.conv, .s = self.conv_state + linear * 8192 * 3 * 4, .a = n }, 32, 1);
