383	                full += 1;
384	            }
385	            self.elem(self.x, self.down, self.x, 2560 * n, 0);
386	            try self.normBatch(l, "post_attention_norm.weight", self.x, self.norm, 2560, 1, 0, n);
387	            self.hadBatch(self.norm, self.trans, 2560, false, n);
388	            try self.layerMatBatch(l, "ffn_gate.weight", self.trans, self.fg, n);
389	            try self.layerMatBatch(l, "ffn_up.weight", self.trans, self.fu, n);
390	            self.elem(self.fg, self.fu, self.mid, 9216 * n, 1);
391	            self.hadBatch(self.mid, self.trans, 9216, false, n);
392	            try self.layerMatBatch(l, "ffn_down.weight", self.trans, self.down, n);
393	            self.elem(self.x, self.down, self.x, 2560 * n, 0);
394	        }
395	        if (with_logits) {
396	            const last = self.x + @as(u64, n - 1) * 2560 * 4;
397	            try self.normOp("output_norm.weight", last, self.norm, 2560, 1, 0);
398	            self.had(self.norm, self.trans, 2560, false);
399	            try self.mat("token_embd.weight", self.trans, self.logits);
